#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

int n, total, answer;
vector<int> vectors[15];
long long sum[15];

void generate(int depth, int num);
void process(int x);

int main() {
    cin >> n;
    generate(0, 0);
    for (int i = 0; i <= 7; ++i) {
        sort(vectors[i].begin(), vectors[i].end());
    }
    total = 0;
    for (int i = 1; i <= 9; ++i) {
        process(i);
    }
    cout << answer << "\n";
    return 0;
}

void generate(int depth, int num) {
    if (depth == 7) return;
    total++;
    int val = ((total - num) % 998244353 + 998244353) % 998244353;
    vectors[depth].push_back(val);
    sum[depth] = (sum[depth] + val) % 1000000007;
    for (int digit = 0; digit <= 9; ++digit) {
        generate(depth + 1, num * 10 + digit);
    }
}

void process(int x) {
    if (x > n) return;
    if (x * 1000000 + 999999 <= n && x * 10000000 > n) {
        int current_total = total;
        for (int i = 0, multiplier = 1; i <= 6; ++i, multiplier *= 10) {
            int size = vectors[i].size();
            int diff = ((current_total - x * multiplier) % 998244353 + 998244353) % 998244353;
            int pos = (int)(lower_bound(vectors[i].begin(), vectors[i].end(), 1000000000 - diff) - vectors[i].begin());
            answer = (answer + diff * size + sum[i]) % 1000000007;
            answer = (answer - 998244353 * (size - pos) % 1000000007 + 1000000007) % 1000000007;
            current_total += size;
        }
        return;
    }
    total++;
    answer = (answer + ((total - x) % 998244353 + 998244353) % 998244353) % 1000000007;
    for (int digit = 0; digit <= 9; ++digit) {
        process(x * 10 + digit);
    }
}
